import{_ as i,a0 as d,w as e,s as l,I as n,x as o,a1 as r,A as s,ao as a}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const y=JSON.parse('{"title":"安卓編年史（32）：安卓 6.0 棉花糖（2） | LCTT x X-CMD","titleTemplate":false,"description":"安卓編年史（32）：安卓 6.0 棉花糖（2） | LCTT (The history of Android) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"安卓編年史（32）：安卓 6.0 棉花糖（2） | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"安卓編年史（32）：安卓 6.0 棉花糖（2） | LCTT (The history of Android) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"The history of Android/32 The (updated) history of Android","title":"安卓編年史（32）：安卓 6.0 棉花糖（2）","tag":"The history of Android","desc":""},"relativePath":"The history of Android/32 The (updated) history of Android.md","filePath":"[post].md"}'),g={name:"The history of Android/32 The (updated) history of Android.md"};function u(m,t,f,T,h,x){const p=d("Link");return e(),l("div",null,[t[25]||(t[25]=n("h1",{id:"安卓編年史-32-安卓-6-0-棉花糖-2",tabindex:"-1"},[o("安卓編年史（32）：安卓 6.0 棉花糖（2） "),n("a",{class:"header-anchor",href:"#安卓編年史-32-安卓-6-0-棉花糖-2","aria-label":"Permalink to “安卓編年史（32）：安卓 6.0 棉花糖（2）”"},"​")],-1)),t[26]||(t[26]=n("h4",{id:"幕後變化",tabindex:"-1"},[o("幕後變化 "),n("a",{class:"header-anchor",href:"#幕後變化","aria-label":"Permalink to “幕後變化”"},"​")],-1)),t[27]||(t[27]=n("p",null,"棉花糖對自棒棒糖引入的節電任務調度器 API 進行了擴展。任務調度器將應用後台進程從隨意喚醒設備規整成一個有組織的系統。任務調度器基本上就是一個後台進程的交通警察。",-1)),n("p",null,[t[1]||(t[1]=o("在棉花糖中，谷歌還添加了一個 “Doze（休眠）”模式來在設備閒置的時候節約更多電量。如果設備靜止不動，未接入電源，並且屏幕處於關閉狀態，它會慢慢進入低功耗離線模式，鎖定後台進程。在一段時間之後，網絡連接會被禁用。喚醒會被鎖定——應用會請求喚醒手機來運行後台進程——而它會被忽略。系統警報（不含用户設置的鬧鐘）以及",-1)),r(p,{href:"http://arstechnica.com/gadgets/2014/11/android-5-0-lollipop-thoroughly-reviewed/6/#h2"},{default:s(()=>[...t[0]||(t[0]=[o("任務調度器",-1)])]),_:1}),t[2]||(t[2]=o("也會被關閉。",-1))]),t[28]||(t[28]=n("p",null,"如果你曾經發現把設備設置為飛行模式，並且注意到電池續航延長了許多，Doze 就像是一個自動的飛行模式，在你手機不用的時候介入——它真的延長了電池續航。它對於整天或整夜放在桌子上的手機很有效，對於平板就更好了，因為它常常被遺忘在咖啡桌上。",-1)),t[29]||(t[29]=n("p",null,"唯一能把設備從 Doze 模式喚醒的來自谷歌雲消息推送服務的“高優先級消息”。這是為信息服務準備的，所以即使設備處於休眠狀態，也能夠收取信息。",-1)),t[30]||(t[30]=n("p",null,[n("img",{src:"https://cdn.arstechnica.net/wp-content/uploads/2015/09/inactive-apps.jpg",alt:""})],-1)),t[31]||(t[31]=n("p",null,"“應用待機”是另一項或多或少有用的節電特性，它在後台靜默運行。這背後的邏輯很簡單：如果你和應用停止交互一段時間，安卓就認為它是不重要的，並取消它訪問網絡和後台進程的權力。",-1)),t[32]||(t[32]=n("p",null,[n("img",{src:"https://cdn.arstechnica.net/wp-content/uploads/2015/09/battery-optimizations.jpg",alt:""})],-1)),t[33]||(t[33]=n("p",null,"對於應用待機而言，和一個應用“交互”意味着打開一個應用，開始一項前台服務，或者生成一條通知。任何其中的一條操作就會重置該應用的待機計時器。對於每種其它邊界情況，谷歌在設置裏添加了一個名字意味模糊的“電池優化”界面。用户可以在這裏設置應用白名單讓它免疫應用待機。至於開發者，他們在開發者設置中有個“不活躍應用”選項可以手動設置應用到待機狀態來測試。",-1)),t[34]||(t[34]=n("p",null,"應用待機主要是自動禁用你不用的應用，這是個對抗垃圾應用或被遺忘的應用消耗電量的好方法。因為它是完全靜默且後台自動執行的，它還能讓新手也能擁有一部精心調教過的設備。",-1)),t[35]||(t[35]=n("p",null,[n("img",{src:"https://cdn.arstechnica.net/wp-content/uploads/2015/10/autobackup.jpg",alt:""})],-1)),n("p",null,[t[4]||(t[4]=o("谷歌在過去幾年嘗試了很多應用備份方案，在棉花糖中它又",-1)),r(p,{href:"http://arstechnica.com/gadgets/2015/10/android-6-0-marshmallow-thoroughly-reviewed/6/#h2"},{default:s(()=>[...t[3]||(t[3]=[o("換了個方案",-1)])]),_:1}),t[5]||(t[5]=o("。棉花糖的暴力應用備份系統的目標是保存整個應用數據文件夾到雲端。這是可能的並且在技術上是可行的，但即便是谷歌自己的應用對它的支持都不怎麼好。設置好一部新安卓手機依然是個大麻煩，要處理無數的登錄和彈出教程。",-1))]),t[36]||(t[36]=a('<p><img src="https://cdn.arstechnica.net/wp-content/uploads/2015/09/BACKUP1.jpg" alt=""></p><p>到界面這裏，棉花糖的備份系統使用了谷歌 Drive 應用。在谷歌 Drive 的設置中有一個“管理備份”界面，不僅會顯示新備份系統的應用數據，還有谷歌過去幾年嘗試的其它應用備份方案的數據。</p><p><img src="https://cdn.arstechnica.net/wp-content/uploads/2016/10/app-linkingf-980x576-980x576.jpg" alt="安卓的應用關聯設置，基本就是一個應用地址轉發系統。 "></p><p>藏在設置裏的還有一個新的“應用關聯”功能，它可以將應用“鏈接”到網站。在應用關聯出現之前，在全新安裝的機器上打開一個谷歌地圖鏈接通常會彈出一個“使用以下方式打開”的對話框，來獲知你是想在瀏覽器還是在谷歌地圖應用中打開這個鏈接。</p><p>這是個愚蠢的問題，因為你當然是想用應用而不是網站——這不就是你安裝這個應用的原因嘛。應用關聯讓網站擁有者可以將他們的應用和網頁相關聯。如果用户安裝了應用，安卓會跳過“使用以下方式打開”直接使用應用。要激活應用關聯，開發者只需要在網站放一些安卓會識別的 json 代碼。</p><p>應用關聯對擁有指定客户端應用的站點來説很棒，比如谷歌地圖、Instagram、Facebook。對於有 API 以及多種客户端的站點，比如 Twitter，應用關聯界面讓用户可以設置任意地址的默認關聯應用。不過默認應用關聯覆蓋了百分之九十的用例，在新手機上大大減少了煩人的彈窗。</p><p><img src="https://cdn.arstechnica.net/wp-content/uploads/2015/09/adopt1.jpg" alt=""></p><p>可選存儲是棉花糖的最佳特性之一。它將 SD 卡從一個二級存儲池轉換成一個完美的合併存儲方案。插入 SD 卡，將它格式化，然後你就有了更多的存儲空間，而這是你從來沒有想過的事情。</p><p><img src="https://cdn.arstechnica.net/wp-content/uploads/2015/09/format1.jpg" alt=""></p><p>插入 SD 卡會彈出一條設置通知，用户可以選擇將卡格式化成“外置”或“內置”存儲。“內置”存儲選項就是新的可選存儲模式，它會將存儲卡格式化為 ext4 文件系統。唯一的缺點？那就是存儲卡和數據都被“鎖定”到你的手機上了。如果不格式化的話，你沒法取出存儲卡茶道其它地方使用。谷歌對於內置存儲的使用場景判斷就是一旦設置就不再更改。</p><p><img src="https://cdn.arstechnica.net/wp-content/uploads/2015/09/removingisbad.jpg" alt=""></p><p>如果你強行拔出了 SD 卡，安卓會盡它最大的努力處理好。它會彈出一條消息“建議最好將 SD 卡插回”和一個“忘記”這張卡的選項。當然“忘記”這張卡將會導致各種數據丟失，建議最好不要這麼做。</p>',12)),n("p",null,[t[7]||(t[7]=o("不幸的是實際上可以使用可選存儲的設備很長時間都沒有出現。Nexus 設備不支持存儲卡，所以為了測試我們插上了一個 U 盤作為我們的可選存儲。OEM 廠商最初抵制這項功能，",-1)),r(p,{href:"http://arstechnica.com/gadgets/2016/02/the-lg-g5-and-galaxy-s7-wont-support-android-6-0s-adoptable-storage/"},{default:s(()=>[...t[6]||(t[6]=[o("LG 和三星",-1)])]),_:1}),t[8]||(t[8]=o("都在他們 2016 年初的旗艦機上禁用了它。三星説“我們相信我們的用户需要 microSD 卡是用來在手機和其它設備之間轉移數據的”，一旦卡被格式化成 ext4 這就不可能了。",-1))]),n("p",null,[t[10]||(t[10]=o("谷歌的實現讓用户可以在外置和內置存儲選項之間選擇。但 OEM 廠商完全拿掉了內置存儲功能，不給用户選擇的機會。高級用户們對此很不高興，並且安卓定製組們很快就重啓啓用了可選存儲。在 Galaxy S7 上，第三方定製組甚至在官方發佈的",-1)),r(p,{href:"http://www.androidpolice.com/2016/03/10/modaco-manages-to-get-adoptable-sd-card-storage-working-on-the-galaxy-s7-and-galaxy-s7-edge-no-root-required/"},{default:s(()=>[...t[9]||(t[9]=[o("的前一天",-1)])]),_:1}),t[11]||(t[11]=o("解除了三星的 SD 卡鎖定。",-1))]),t[37]||(t[37]=a('<h4 id="音量和通知" tabindex="-1">音量和通知 <a class="header-anchor" href="#音量和通知" aria-label="Permalink to “音量和通知”">​</a></h4><p><img src="https://cdn.arstechnica.net/wp-content/uploads/2016/10/1-2-1440x1454.jpg" alt=""></p><p>為了更簡潔的設計，谷歌將通知優先級控制從音量彈窗中移除了。按下音量鍵會彈出一個單獨的滑動條，對應當前音源控制，還有一個下拉按鈕可以展開控制面板，顯示所有的三個聲音控制條：通知，媒體和鬧鐘。所有的通知優先級控制還在——它們現在在一個“勿擾模式”的快速設置方塊中。</p><p><img src="https://cdn.arstechnica.net/wp-content/uploads/2015/09/dnd1.jpg" alt=""></p><p>通知控制最有用的新功能之一是允許用户控制抬頭通知——現在叫“預覽”通知。這項功能讓通知在屏幕頂部彈出，就像 iOS 那樣。谷歌認為最重要的通知應該提升到高於你普通日常通知的地位。</p><p><img src="https://cdn.arstechnica.net/wp-content/uploads/2015/09/2015-09-13-05.13.49.png" alt=""></p><p>但是，在棒棒糖中，這項特性引入的時候，谷歌糟糕地讓開發者來決定他們的應用是否“重要”。毫無疑問，所有開發者都認為他的應用是世界上最重要的東西。所以儘管最初這項特性是為你親密聯繫人的即時消息設計的，最後變成了被 Facebook 的點贊通知所操控。在棉花糖中，每個應用在通知設置都有一個“設置為優先”複選框，給了用户一把大錘來收拾不守規矩的應用。</p><hr><p>作者簡介：</p><p>Ron 是 Ars Technica 的評論編緝，專注於安卓系統和谷歌產品。他總是在追尋新鮮事物，還喜歡拆解事物看看它們到底是怎麼運作的。</p><hr>',11)),n("p",null,[t[13]||(t[13]=o("via: ",-1)),r(p,{href:"http://arstechnica.com/gadgets/2016/10/building-android-a-40000-word-history-of-googles-mobile-os/32/"},{default:s(()=>[...t[12]||(t[12]=[o("http://arstechnica.com/gadgets/2016/10/building-android-a-40000-word-history-of-googles-mobile-os/32/",-1)])]),_:1})]),n("p",null,[t[17]||(t[17]=o("作者：",-1)),r(p,{href:"http://arstechnica.com/author/ronamadeo"},{default:s(()=>[...t[14]||(t[14]=[o("RON AMADEO",-1)])]),_:1}),t[18]||(t[18]=o(" 譯者：",-1)),r(p,{href:"https://github.com/alim0x"},{default:s(()=>[...t[15]||(t[15]=[o("alim0x",-1)])]),_:1}),t[19]||(t[19]=o(" 校對：",-1)),r(p,{href:"https://github.com/wxy"},{default:s(()=>[...t[16]||(t[16]=[o("wxy",-1)])]),_:1})]),n("p",null,[t[22]||(t[22]=o("本文由 ",-1)),r(p,{href:"https://github.com/LCTT/TranslateProject"},{default:s(()=>[...t[20]||(t[20]=[o("LCTT",-1)])]),_:1}),t[23]||(t[23]=o(" 原創編譯，",-1)),r(p,{href:"https://linux.cn/"},{default:s(()=>[...t[21]||(t[21]=[o("Linux中國",-1)])]),_:1}),t[24]||(t[24]=o(" 榮譽推出",-1))])])}const b=i(g,[["render",u]]);export{y as __pageData,b as default};
